<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import GovernanceListFrame from './GovernanceListFrame.vue';import GovernanceResourcePicker from './GovernanceResourcePicker.vue';import {useGovernanceList} from './useGovernanceList';import {localTime,stateLabels,type EvaluationPage,type CandidateDetail} from './workbench-types';
const app=useApplication(),ops=app.operationsCommands,router=useRouter(),list=useGovernanceList<EvaluationPage>('evaluations'),create=ref(false),candidateId=ref(''),datasetId=ref(''),candidate=ref<CandidateDetail|null>(null),busy=ref(false),error=ref('');let epoch=0;
const locked=computed(()=>busy.value||ops.pending.value||!ops.available.value);
watch(candidateId,async id=>{const turn=++epoch;candidate.value=null;error.value='';if(!id)return;try{const value=await ops.read<CandidateDetail>('/api/v1/operations/candidates/'+id);if(turn===epoch)candidate.value=value;}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'候选配置暂不可用。';}});
async function evaluate(){if(locked.value||!candidate.value)return;busy.value=true;error.value='';try{const run=await ops.submit(`/api/v1/operations/candidates/${candidate.value.id}/evaluations`,{expectedRevisionToken:candidate.value.revisionToken,datasetId:datasetId.value}) as {id:string};create.value=false;await router.push('/operations/evaluation/'+run.id);}catch(cause){error.value=cause instanceof Error?cause.message:'评测尚未确认，请保留原请求。';}finally{busy.value=false;}}
onUnmounted(()=>epoch++);
</script>
<template><GovernanceListFrame title="质量评测" description="逐样本记录实际输出，按任务类型判定质量，保留失败与人工复核依据。" :counts="list.page.value?.counts??{}" :total="list.page.value?.total??null" :loading="list.loading.value" :error="list.error.value" v-model:query="list.query.value" :state="list.state()" :states="['RUNNING','COMPLETED','CANCELLED','PENDING']" :next-cursor="list.page.value?.nextCursor" :has-cursor="list.hasCursor()" @search="list.search" @filter="list.filter('state',$event)" @refresh="list.load" @next="list.next" @first="list.first"><template #actions><RouterLink class="btn" to="/operations/evaluation/datasets"><Icon name="layers"/>数据集管理</RouterLink><button class="btn primary" :disabled="locked" @click="create=true;candidateId='';datasetId='';error=''"><Icon name="play"/>新建评测</button></template><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>数据集版本</th><th>运行状态</th><th>评测依据</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.page.value?.items" :key="item.id"><td class="primary-cell"><RouterLink class="gov-link" :to="'/operations/evaluation/'+item.id">{{item.title}}</RouterLink><span class="sub-cell">{{item.id.slice(0,8)}}</span></td><td><span class="gov-tag" :data-state="item.state">{{item.state==='PENDING'?'排队中':stateLabels[item.state]}}</span></td><td><span v-if="item.candidateId">候选修订 {{item.candidateRevision}}</span><span v-else class="gov-muted">历史观察评测</span><span v-if="item.reviewReason" class="sub-cell">已人工复核</span></td><td>{{localTime(item.createdAt)}}</td><td><RouterLink class="gov-link" :to="'/operations/evaluation/'+item.id">查看报告</RouterLink></td></tr></tbody></table></div><div v-if="!list.page.value?.items.length" class="gov-empty"><Icon name="layers" :size="32"/><h3>还没有评测记录</h3><p>准备数据集与候选配置后，即可开始一次可复现的评测。</p></div></GovernanceListFrame><p class="gov-disclosure">本地受控环境的评测用于验证流程、协议和指标计算。真实业务质量需使用具备代表性且有授权的样本验证。</p>
<GovernanceDrawer v-if="create" title="新建质量评测" subtitle="运行时冻结数据集、候选配置与判定规则。" wide :busy="busy" @close="create=false"><p v-if="error" class="gov-error" role="alert">{{error}}</p><div class="gov-fields"><GovernanceResourcePicker module="candidates" state="DRAFT" v-model="candidateId" label="候选配置" :disabled="locked"/><dl v-if="candidate" class="gov-definition"><dt>语音模型</dt><dd>{{candidate.configuration.modelVersion}}</dd><dt>纪要提示词</dt><dd>{{candidate.configuration.promptVersion}}</dd><dt>匹配阈值</dt><dd>{{candidate.configuration.voiceThreshold??'匹配关闭'}}</dd><dt>内容指纹</dt><dd>{{candidate.contentSha}}</dd></dl><GovernanceResourcePicker module="datasets" v-model="datasetId" label="评测数据集" :disabled="locked"/><div class="gov-note">系统逐个处理样本。实时录音或离线语音任务占用资源时，评测会等待；已完成的结果会持久保存。</div><RouterLink class="gov-link" to="/operations/configuration">还没有配置？前往创建候选配置 →</RouterLink></div><template #footer><button class="btn" :disabled="busy" @click="create=false">关闭</button><button class="btn primary" :disabled="locked||!candidate||!datasetId||candidate.state!=='DRAFT'" @click="evaluate">开始评测</button></template></GovernanceDrawer></template>
